// std::vector: Dynamic size, RAII, Safety features

std::vector<int> v = {10, 20};
v.push_back(30);                // Automatic resizing/growth
size_t current_size = v.size();

try {
    v.at(100) = 0;              // Bounds check (throws std::out_of_range)
} catch (...) {}

// C-Style Array: Fixed size, Manual memory management (if heap allocated)

const int N = 5;
int fixed_arr[N];               // Size fixed at initialization
fixed_arr[N - 1] = 42;

// Undefined Behavior: No bounds checking on [] access
int dangerous = fixed_arr[N + 10];

int* heap_arr = new int[N];     // Manual heap allocation
delete[] heap_arr;              // Manual memory cleanup required
